package org.brightstats.data;
import java.util.*;
import com.google.gson.*;
import org.brightstats.stats.*;
/** Rebind saved latent specifications when model nodes are removed; surviving identities keep their roles. */
public final class LatentDiagramSettings {
    private LatentDiagramSettings(){}
    private static int count(int[] mapping){Set<Integer> values=new HashSet<>();for(int value:mapping)if(value< -1||value>=0&&!values.add(value))throw new IllegalArgumentException("Invalid construct-removal mapping.");for(int index=0;index<values.size();index++)if(!values.contains(index))throw new IllegalArgumentException("Construct mapping must remain contiguous.");return values.size();}
    private static int mapped(int index,int[] mapping){if(index<0||index>=mapping.length)throw new IllegalArgumentException("Saved construct index differs from the diagram.");return mapping[index];}
    public static JsonObject nonlinear(JsonObject settings,int[] mapping){if(settings==null)return null;if(count(mapping)<2)return null;var old=NonlinearInput.specification(settings.get("specification"));List<NonlinearPls.Extension> extensions=new ArrayList<>();for(var extension:old.extensions()){int target=mapped(extension.target(),mapping);int[] factors=Arrays.stream(extension.factors()).map(index->mapped(index,mapping)).toArray();if(target>=0&&Arrays.stream(factors).allMatch(value->value>=0))extensions.add(new NonlinearPls.Extension(target,factors));}List<PathProcess.Probe> probes=new ArrayList<>();for(var probe:old.probes()){Map<Integer,Double> values=new LinkedHashMap<>();for(var entry:probe.values().entrySet()){int index=mapped(entry.getKey(),mapping);if(index>=0)values.put(index,entry.getValue());}probes.add(new PathProcess.Probe(values.size()==probe.values().size()?probe.name():probe.name()+" (removed score omitted)",values));}NonlinearPls.Grid grid=null;if(old.grid()!=null){var source=old.grid();int x=mapped(source.source(),mapping),y=mapped(source.target(),mapping);if(x>=0&&y>=0)grid=new NonlinearPls.Grid(x,y,source.lower(),source.upper(),source.points());}var result=settings.deepCopy();result.add("specification",new Gson().toJsonTree(new NonlinearPls.Specification(extensions,probes,grid)));return result;}
    public static JsonObject higherOrder(JsonObject settings,int[] mapping){if(settings==null)return null;if(count(mapping)<2)return null;var old=HigherOrderInput.specification(settings.get("specification"));List<Integer> retained=new ArrayList<>();int[] secondMapping=new int[old.retained().length+old.higherOrder().size()];Arrays.fill(secondMapping,-1);int[] originalRetained=old.retained();for(int index=0;index<originalRetained.length;index++){int source=mapped(originalRetained[index],mapping);if(source>=0){secondMapping[index]=retained.size();retained.add(source);}}List<HigherOrderPls.Dimension> dimensions=new ArrayList<>();for(int index=0;index<old.higherOrder().size();index++){var original=old.higherOrder().get(index);int[] columns=original.lowerOrder();double[] weights=original.initialWeights();List<Integer> selected=new ArrayList<>();List<Double> selectedWeights=new ArrayList<>();for(int j=0;j<columns.length;j++){int next=mapped(columns[j],mapping);if(next>=0){selected.add(next);selectedWeights.add(weights[j]);}}if(selected.size()>=2&&selectedWeights.stream().anyMatch(value->value!=0)){secondMapping[originalRetained.length+index]=retained.size()+dimensions.size();dimensions.add(new HigherOrderPls.Dimension(original.name(),selected.stream().mapToInt(Integer::intValue).toArray(),original.mode(),original.measurementType(),selectedWeights.stream().mapToDouble(Double::doubleValue).toArray()));}}if(dimensions.isEmpty())return null;List<PlsSem.Edge> edges=new ArrayList<>();for(var edge:old.edges()){if(edge.source()<0||edge.target()<0||edge.source()>=secondMapping.length||edge.target()>=secondMapping.length)throw new IllegalArgumentException("Saved stage-two edge differs from model order.");int source=secondMapping[edge.source()],target=secondMapping[edge.target()];if(source>=0&&target>=0)edges.add(new PlsSem.Edge(source,target));}var result=settings.deepCopy();result.add("specification",new Gson().toJsonTree(new HigherOrderPls.Specification(retained.stream().mapToInt(Integer::intValue).toArray(),dimensions,edges,old.options())));return result;}
}
